def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    # Find colored components, excluding background and the 5-line.
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if g[r][c] in (0, 5) or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                rr, cc = stack.pop()
                comp.append((rr, cc))
                for nr, nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if (0 <= nr < h and 0 <= nc < w and
                        g[nr][nc] not in (0, 5) and (nr, nc) not in seen):
                        seen.add((nr, nc))
                        stack.append((nr, nc))
            comps.append(comp)

    # Maximal straight runs of 5.
    lines = []
    for r in range(h):
        c = 0
        while c < w:
            if g[r][c] != 5:
                c += 1
                continue
            a = c
            while c < w and g[r][c] == 5:
                c += 1
            if c - a >= 2:
                lines.append(("H", r, a, c - 1))

    for c in range(w):
        r = 0
        while r < h:
            if g[r][c] != 5:
                r += 1
                continue
            a = r
            while r < h and g[r][c] == 5:
                r += 1
            if r - a >= 2:
                lines.append(("V", c, a, r - 1))

    for orient, fixed, lo, hi in lines:
        for comp in comps:
            cells = set(comp)
            r0 = min(r for r, c in comp)
            r1 = max(r for r, c in comp)
            c0 = min(c for r, c in comp)
            c1 = max(c for r, c in comp)

            if orient == "V":
                # Seed lies beside the vertical line.
                touches = any(
                    (r, fixed - 1) in cells or (r, fixed + 1) in cells
                    for r in range(lo, hi + 1)
                    if 0 <= fixed - 1 < w or 0 <= fixed + 1 < w
                )
                if not touches:
                    continue
                for r in range(lo, hi + 1):
                    sr = r0 + (r - r0) % (r1 - r0 + 1)
                    for c in range(c0, c1 + 1):
                        if (sr, c) in cells:
                            g[r][c] = g[sr][c]
            else:
                # Seed lies above or below the horizontal line.
                touches = any(
                    (fixed - 1, c) in cells or (fixed + 1, c) in cells
                    for c in range(lo, hi + 1)
                    if 0 <= fixed - 1 < h or 0 <= fixed + 1 < h
                )
                if not touches:
                    continue
                for c in range(lo, hi + 1):
                    sc = c0 + (c - c0) % (c1 - c0 + 1)
                    for r in range(r0, r1 + 1):
                        if (r, sc) in cells:
                            g[r][c] = g[r][sc]

    return g
